for id in ['42923','42925','42939','42947','42949','42963','43052','ECON-EC-MEDIUMBOSS-18018']:
    q=B[id]['q'];s=re.sub(r'^(In this setting, |An economist observes that |Evidence indicates that )','',q['q']);s=s[0].upper()+s[1:]
    assert M[id]['state']=='UNREVIEWED'
    P[id]={'q':s,'correct_index':B[id]['answer'],'rationale':['Remove the demonstrated empty attribution wrapper; retain the existing distinct causal task and structural role.']}
    U[id]={'reason':P[id]['rationale'][0],'faculty_precedents':['43006','42980','42987'],'scope':'unreviewed direct wording'}
(HERE/'unreviewed_scope.json').write_text(json.dumps(U,ensure_ascii=False,indent=2),encoding='utf-8')
